?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Referral Analytics | TechSelectAI</title><style>body{font-family:Inter,Arial,sans-serif;margin:0;background:#f7f9fc;color:#172033}.wrap{max-width:1120px;margin:32px auto;padding:0 20px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:20px;margin:18px 0}h1,h2{color:#123b67}.muted{color:#64748b}.filters a{display:inline-block;margin-right:8px;padding:8px 11px;border:1px solid #cbd5e1;border-radius:9px;text-decoration:none;color:#123b67;background:#fff}.table{width:100%;border-collapse:collapse}.table th,.table td{text-align:left;padding:11px;border-bottom:1px solid #e2e8f0;vertical-align:top}.table th{font-size:12px;color:#64748b}.notice{padding:14px;border-radius:10px;background:#fff7df;border:1px solid #f1d48a}.stat{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px}.stat div{padding:14px;background:#f8fbfd;border-radius:12px}.stat strong{display:block;font-size:24px;color:#123b67}@media(max-width:700px){.table-wrap{overflow:auto}.table{min-width:720px}}</style></head><body><main class="wrap"><h1>AI Referral Analytics</h1><p class="muted">Privacy-minimized traffic attributed to recognized AI assistant/search referrers on public TechSelectAI knowledge pages. No IP address, cookies, prompt text, raw user agent, or referrer query string is stored.</p><div class="filters"><a href="?days=7">7 days</a><a href="?days=30">30 days</a><a href="?days=90">90 days</a></div><?php if($error):?><div class="panel notice"><?=ar_e($error)?></div><?php else:$total=array_sum(array_map(fn($r)=>(int)$r['hits'],$data['by_source']));?><section class="panel"><div class="stat"><div><span class="muted">Period</span><strong><?=intval($data['days'])?> days</strong></div><div><span class="muted">Recognized AI referrals</span><strong><?=intval($total)?></strong></div><div><span class="muted">Sources seen</span><strong><?=count($data['by_source'])?></strong></div></div></section><section class="panel"><h2>By AI source</h2><div class="table-wrap"><table class="table"><thead><tr><th>Source</th><th>Hits</th><th>Landing pages</th><th>Last seen</th></tr></thead><tbody><?php foreach($data['by_source'] as $r):?><tr><td><?=ar_e(ucfirst($r['source_provider']))?></td><td><?=intval($r['hits'])?></td><td><?=intval($r['landing_pages'])?></td><td><?=ar_e($r['last_seen'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel"><h2>Top landing pages</h2><div class="table-wrap"><table class="table"><thead><tr><th>Landing page</th><th>Source</th><th>Hits</th><th>Last seen</th></tr></thead><tbody><?php foreach($data['by_landing'] as $r):?><tr><td><a href="<?=ar_e($r['landing_path'])?>"><?=ar_e($r['landing_path'])?></a></td><td><?=ar_e($r['source_provider'])?></td><td><?=intval($r['hits'])?></td><td><?=ar_e($r['last_seen'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></body></html>